const head = $('Contrôler la réponse HTTP').first().json;
const get = $('Inspecter page GET').first().json;
const optionsResponse = $input.first().json;
const response = get;
const cfg = $('Paramètres de l’audit').first().json;
const url = String(cfg.url || '');
const domain = String(cfg.authorized_domain || '');
if(!/^https?:\/\//i.test(url)) throw Error('URL cible invalide : indiquer https://...');
const hdr=Object.fromEntries(Object.entries(response.headers||{}).map(([k,v])=>[k.toLowerCase(),Array.isArray(v)?v.join('; '):String(v)]));
const h=(k)=>hdr[k]||'';
const findings=[];
const add=(level,check,observation,action)=>findings.push({level,check,observation,action});
const status=Number(response.statusCode||0);
const headStatus=Number(head.statusCode||0);
const optionsStatus=Number(optionsResponse.statusCode||0);
const optionsHeaders=Object.fromEntries(Object.entries(optionsResponse.headers||{}).map(([k,v])=>[k.toLowerCase(),String(v)]));
if(headStatus===405||headStatus===501) add('info','Contrôle HEAD','La méthode HEAD n’est pas acceptée.','Ce n’est pas une faille. Le contrôle GET reste disponible.');
if(optionsStatus===405||optionsStatus===501) add('info','Contrôle OPTIONS','La méthode OPTIONS n’est pas acceptée.','Ce n’est pas une faille. Vérifier uniquement si l’application a besoin de cette méthode.');
if(optionsHeaders['access-control-allow-origin']==='*' && optionsHeaders['access-control-allow-credentials']==='true') add('medium','Configuration CORS','En-têtes CORS larges et identifiants autorisés observés.','Faire confirmer par l’équipe web le comportement réel des navigateurs et les origines autorisées.');
if(status>=300 && status<400) add('info','Redirection','Le site renvoie une redirection ; le workflow ne la suit pas pour rester dans le périmètre.','Auditer séparément l’adresse finale après validation de son appartenance au périmètre.');
if(!/^https:\/\//i.test(url)) add('high','HTTPS','Le lien fourni utilise HTTP, sans chiffrement du transport.','Utiliser HTTPS et mettre en place une redirection HTTP vers HTTPS.');
if(status===0) add('high','Accessibilité','Pas de code HTTP exploitable.','Vérifier accès, réseau et réponse serveur.');
else if(status===405||status===501) add('info','Méthode HEAD','Le serveur ne permet pas le contrôle par HEAD.','Compléter par un contrôle GET autorisé.');
else if(status>=400) add('medium','Statut HTTP','Le serveur renvoie le code '+status+'.','Vérifier cette réponse et les chemins de redirection.');
if(!h('strict-transport-security')) add('medium','HSTS','En-tête HSTS absent sur cette réponse.','Étudier l’activation de HSTS lorsque HTTPS est opérationnel partout.');
else if(!/max-age=\d+/i.test(h('strict-transport-security'))) add('low','HSTS','Directive max-age absente.','Ajouter un max-age HSTS valide.');
if(!h('content-security-policy')) add('medium','Content-Security-Policy','Politique CSP non observée sur cette réponse.','Élaborer une CSP adaptée et la tester d’abord en mode Report-Only.');
if(!/nosniff/i.test(h('x-content-type-options'))) add('medium','X-Content-Type-Options','La valeur nosniff n’est pas présente.','Ajouter X-Content-Type-Options: nosniff.');
if(!h('x-frame-options') && !/frame-ancestors/i.test(h('content-security-policy'))) add('medium','Protection contre les cadres','Aucune protection X-Frame-Options ou frame-ancestors observée.','Ajouter frame-ancestors dans CSP ou une politique X-Frame-Options adaptée.');
if(!h('referrer-policy')) add('low','Referrer-Policy','Politique de transmission de l’adresse précédente non observée.','Évaluer strict-origin-when-cross-origin.');
if(!h('permissions-policy')) add('low','Permissions-Policy','Politique de contrôle des fonctionnalités navigateur non observée.','Restreindre les fonctionnalités non nécessaires.');
if(h('server')) add('info','Bannière serveur','Le serveur communique une indication logicielle.','Éviter d’exposer les versions détaillées si possible.');
if(h('x-powered-by')) add('low','X-Powered-By','Une technologie est révélée par un en-tête HTTP.','Masquer cet en-tête si non nécessaire.');
if(h('set-cookie')) add('info','Cookies','Des cookies sont visibles, mais cette réponse ne permet pas une revue exhaustive.','Contrôler séparément tous les cookies de session, leurs attributs Secure, HttpOnly et SameSite.');
const weight={high:20,medium:10,low:3,info:0};
const score=Math.max(0,100-findings.reduce((s,f)=>s+(weight[f.level]||0),0));
const counts=Object.fromEntries(['high','medium','low','info'].map(k=>[k,findings.filter(f=>f.level===k).length]));
return [{json:{target:url,domain,authorization_reference:cfg.authorization_reference,checks_executed:['HEAD','GET','OPTIONS'],checked_at:new Date().toISOString(),status_code:status,score_indicatif:score,counts,findings,headers_observed:Object.keys(hdr),limitations:'Audit autorisé à faible impact : 3 requêtes HTTP (HEAD, GET, OPTIONS) sans suivi de redirections. Pas de tests de charge, injection, exploitation, analyse TLS complète ni contrôle exhaustif des cookies. Le score est une aide à la priorisation et non une garantie de sécurité.',note:'Score pédagogique, non normalisé et non assimilable à une certification.'}}];

