function wrap(s,width=82){let words=ascii(s).split(/\s+/), rows=[],cur='';for(const word of words){if(!word)continue;if((cur+' '+word).trim().length>width&&cur){rows.push(cur);cur='';}if(word.length>width){if(cur){rows.push(cur);cur='';}for(let i=0;i<word.length;i+=width)rows.push(word.slice(i,i+width));}else cur+=(cur?' ':'')+word;}if(cur)rows.push(cur);return rows;}
function para(s,x,top,width=88,size=10,leading=15,color=palette.ink){let rows=wrap(s,width);for(let i=0;i<rows.length;i++)txt(rows[i],x,top+i*leading,size,color);return rows.length*leading;}
function newPage(section){if(commands.length)pages.push(commands.join('\n')+'\n');commands=[];rect(0,0,W,11,palette.blue);rect(0,11,W,72,palette.navy);txt('AUDIT DE SECURITE WEB',margin,29,16,palette.white,'F2');txt(section,margin,57,9,'#B8D3F4');line(margin,795,W-margin,795);txt('Audit de configuration HTTP - controles non intrusifs',margin,808,8,palette.muted);y=104;}
