rect(margin,y,507,155,palette.light);
txt('INDICE PEDAGOGIQUE',margin+18,y+16,10,palette.muted,'F2');
txt(String(score)+'/100',margin+18,y+42,39,scoreCol,'F2');
bar(margin+18,y+114,219,11,score/100,scoreCol);
