txt('Il resume seulement les controles effectues.',margin+257,y+47,9,palette.ink);
txt('Reponse HTTP : '+String(audit.status_code??'non disponible'),margin+257,y+83,11,palette.navy,'F2');
y+=181;
section('Repartition des observations');
const tiles=[['A EXAMINER',cnt.high||0,palette.red],['A PLANIFIER',cnt.medium||0,palette.amber],['A AMELIORER',cnt.low||0,palette.blue],['A CONFIRMER',cnt.info||0,palette.muted]];
tiles.forEach((t,i)=>{let x=margin+(i%2)*260, yy=y+Math.floor(i/2)*90;rect(x,yy,247,77,palette.light);rect(x,yy,5,77,t[2]);txt(String(t[1]),x+15,yy+8,25,t[2],'F2');txt(t[0],x+67,yy+29,10,palette.ink,'F2');});
y+=198;
