// STOP before any network call unless the customer explicitly approved this hostname.
const cfg=$input.first().json;
const url=String(cfg.url||'').trim();
const match=/^https:\/\/([^\/:?#]+)(?:[:\/\?#]|$)/i.exec(url);
if(!match) throw Error('HTTPS requis. Adresse invalide ou hôte manquant.');
const host=match[1].toLowerCase();
if(/^(?:\d{1,3}\.){3}\d{1,3}$/.test(host)||host.includes(':')) throw Error('Utiliser un nom DNS validé, pas une IP.');
if(host==='localhost'||host.endsWith('.local')||host.endsWith('.internal')) throw Error('Cible interne non prise en charge dans ce mode.');
