if(cfg.authorization_confirmed!==true || !String(cfg.authorization_reference||'').trim()) throw Error('Autorisation écrite : confirmer et indiquer sa référence avant de démarrer.');
return [{json:{url,authorized_domain:host,authorization_reference:cfg.authorization_reference}}];
